from scipy.spatial.transform import Rotation as Rotation
from scipy.optimize import least_squares

def tf(p=(0,0,0),r=(0,0,0)):
    T=np.eye(4);T[:3,:3]=Rotation.from_euler('xyz',r).as_matrix();T[:3,3]=p;return T
ORIGINS=[tf((0,0,.333)),tf(r=(-np.pi/2,0,0)),tf((0,-.316,0),(np.pi/2,0,0)),tf((.0825,0,0),(np.pi/2,0,0)),tf((-.0825,.384,0),(-np.pi/2,0,0)),tf(r=(np.pi/2,0,0)),tf((.088,0,0),(np.pi/2,0,0))]
def fk(q):
    T=tf((0,-.4,.78),(0,0,np.pi/2))
    for O,a in zip(ORIGINS,q):T=T@O@tf(r=(0,0,a))
    return T@tf((0,0,.107),(0,0,-np.pi/4))
def ik(pos,rot,q):
    lim=np.array(r.spec()['action_types']['joint_position']['panda_joint_limits_rad'])
    def error(x):
        T=fk(x)
        return np.r_[5*(T[:3,3]-pos),Rotation.from_matrix(rot@T[:3,:3].T).as_rotvec(),.005*(x-q)]
    sol=least_squares(error,q,bounds=(lim[:,0]+.001,lim[:,1]-.001),max_nfev=300)
    if np.linalg.norm(fk(sol.x)[:3,3]-pos)>.005:raise ValueError(('unreachable',pos,sol.fun))
    return sol.x
PY
